template.query:
query EnhancedTableStats($tableId: ID!) {
        table(id: $tableId) {
          id
          identifier
          description
          nodeCount
          attributeCount
          createdAt
          updatedAt
        }
        nodes: nodes(
          filter: { tableId: $tableId }
          pagination: { limit: 100, offset: 0 }
        ) {
          totalCount
          hasNextPage
          nodes {
            id
            content
            createdAt
            attributes {
              id
              value
              attribute {
                identifier
                dataType
              }
            }
          }
        }
      }
